import { sql } from 'drizzle-orm'
import { boolean, index, pgTable, text, timestamp, unique, uuid } from 'drizzle-orm/pg-core'

// Better Auth tables (ARCHITECTURE.md section 7.1). Field names match Better
// Auth's core schema (verified by tests/integration/auth-schema.test.ts).
// IDs are generated by PostgreSQL (D-28); Better Auth runs with
// advanced.database.generateId = false and never supplies its own.

const id = () => uuid().primaryKey().default(sql`uuidv7()`)
const timestamps = {
  createdAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
  updatedAt: timestamp({ withTimezone: true }).notNull().defaultNow(),
}

export const user = pgTable('user', {
  id: id(),
  name: text().notNull(),
  email: text().notNull().unique(),
  emailVerified: boolean().notNull().default(false),
  image: text(),
  ...timestamps,
})

export const session = pgTable('session', {
  id: id(),
  expiresAt: timestamp({ withTimezone: true }).notNull(),
  token: text().notNull().unique(),
  ipAddress: text(),
  userAgent: text(),
  userId: uuid().notNull().references(() => user.id, { onDelete: 'cascade' }),
  ...timestamps,
}, table => [index('session_user_id_idx').on(table.userId)])

export const account = pgTable('account', {
  id: id(),
  accountId: text().notNull(),
  providerId: text().notNull(),
  userId: uuid().notNull().references(() => user.id, { onDelete: 'cascade' }),
  accessToken: text(),
  refreshToken: text(),
  idToken: text(),
  accessTokenExpiresAt: timestamp({ withTimezone: true }),
  refreshTokenExpiresAt: timestamp({ withTimezone: true }),
  scope: text(),
  password: text(),
  ...timestamps,
}, table => [
  index('account_user_id_idx').on(table.userId),
  // Not in Better Auth's default schema: one provider identity maps to exactly one account.
  unique('account_provider_account_unique').on(table.providerId, table.accountId),
])

export const verification = pgTable('verification', {
  id: id(),
  identifier: text().notNull(),
  value: text().notNull(),
  expiresAt: timestamp({ withTimezone: true }).notNull(),
  ...timestamps,
}, table => [index('verification_identifier_idx').on(table.identifier)])
